#!/usr/bin/env python3
"""Validate the bilingual documentation tree.

Read-only, standard library only, no network, no writes to the repository.
Runs on every push and pull request so a broken link, a missing translation
or a stray generation marker is caught before it reaches main.

Five checks:

  bad-link    relative links must resolve to a file that exists
  bad-anchor  local #anchors must match a heading in the target document
  marker      no translation or machine-generation labels
  fence       fenced code blocks must be balanced
  pairing     every document needs its counterpart in the other language

Before scanning, the script builds a deliberately broken tree in a temporary
directory and asserts that all five detectors fire. A checker that cannot
detect a known fault must never be allowed to report a clean tree.
"""

from __future__ import annotations

import os
import re
import sys
import tempfile
from pathlib import Path

# Phrases that would mark a page as translated or machine-produced. Deliberately
# narrow: ordinary prose such as "中文版" in a sentence is perfectly fine.
MARKERS = (
    "本文是中文版",
    "本文是英文版",
    "本文件是中文版",
    "翻译自",
    "译自",
    "中文翻译",
    "机器翻译",
    "逐句翻译",
    "由 AI 生成",
    "AI 生成",
    "AI-generated",
    "generated by AI",
    "作为人工智能",
    "本文由",
    "本文件由",
    "This is the Chinese",
    "This is the English",
    "translated from",
    "简体中文版；",
)

LINK = re.compile(r"\]\(([^)]+)\)")
HEADING = re.compile(r"^#{1,6}\s+(.*?)\s*#*\s*$")
SKIP_SCHEMES = ("http://", "https://", "mailto:", "<", "data:")


def slug(title: str) -> str:
    """Approximate the anchor GitHub generates for a heading."""
    s = title.strip().lower()
    s = re.sub(r"[^\w\u4e00-\u9fff \-]", "", s, flags=re.UNICODE)
    return s.replace(" ", "-")


def headings(path: Path) -> list[str]:
    out = []
    for line in path.read_text(encoding="utf-8").splitlines():
        m = HEADING.match(line)
        if m:
            out.append(slug(m.group(1)))
    return out


def counterpart(rel: str) -> str:
    """Expected path of the same page in the other language.

    Two naming conventions are in use: ``NAME.md`` / ``NAME.zh-CN.md``, and
    for the interview FAQ ``NAME-en.md`` / ``NAME-zh.md``.
    """
    if rel.endswith(".zh-CN.md"):
        return rel[: -len(".zh-CN.md")] + ".md"
    if rel.endswith("-zh.md"):
        return rel[: -len("-zh.md")] + "-en.md"
    if rel.endswith("-en.md"):
        return rel[: -len("-en.md")] + "-zh.md"
    return rel[: -len(".md")] + ".zh-CN.md"


def scan(root: Path) -> tuple[list[tuple[str, str, str]], dict[str, int]]:
    """Return (problems, counters). A problem is (kind, file, detail)."""
    problems: list[tuple[str, str, str]] = []
    md: list[Path] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d != ".git"]
        for name in filenames:
            if name.endswith(".md"):
                md.append(Path(dirpath) / name)

    stats = {"files": len(md), "links": 0, "anchors": 0, "pairs": 0}
    relpaths = {p.relative_to(root).as_posix() for p in md}

    for p in md:
        rel = p.relative_to(root).as_posix()
        text = p.read_text(encoding="utf-8")

        for word in MARKERS:
            if word in text:
                problems.append(("marker", rel, f"found {word!r}"))

        if text.count("```") % 2:
            problems.append(("fence", rel, "odd number of ``` fences"))

        for m in LINK.finditer(text):
            target = m.group(1).strip()
            if target.startswith(SKIP_SCHEMES):
                continue
            path_part, _, anchor = target.partition("#")
            path_part = path_part.split(" ")[0].strip()
            anchor = anchor.split(" ")[0].strip()

            if path_part:
                stats["links"] += 1
                resolved = (p.parent / path_part).resolve()
                if not resolved.exists():
                    problems.append(("bad-link", rel, target))
                    continue
                doc = resolved
            else:
                doc = p

            if anchor and doc.suffix == ".md" and doc.exists():
                stats["anchors"] += 1
                if anchor not in headings(doc):
                    problems.append(("bad-anchor", rel, target))

        stats["pairs"] += 1
        other = counterpart(rel)
        if other not in relpaths:
            problems.append(("pairing", rel, f"missing {other}"))

    return problems, stats


def self_test() -> None:
    """Prove every detector fires on a known-broken tree before trusting it."""
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        (root / "a.md").write_text(
            "[bad](gone.md)\n"
            "[anchor](b.md#missing-heading)\n"
            "翻译自 some other document\n"
            "```python\nx = 1\n",
            encoding="utf-8",
        )
        (root / "a.zh-CN.md").write_text(
            "[English](a.md) | 简体中文\n\n## Existing\n\ntext\n",
            encoding="utf-8",
        )
        (root / "b.md").write_text(
            "## Real Heading\n\ntext\n",
            encoding="utf-8",
        )
        problems, _ = scan(root)
        fired = {kind for kind, _, _ in problems}
        expected = {"bad-link", "bad-anchor", "marker", "fence", "pairing"}
        missing = expected - fired
        if missing:
            print(
                "[docs-check] SELF-TEST FAILED, detectors did not fire: "
                + ", ".join(sorted(missing)),
                file=sys.stderr,
            )
            sys.exit(2)
        print(f"[docs-check] self-test: {len(expected)}/{len(expected)} detectors armed")


def main() -> int:
    root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    self_test()
    problems, stats = scan(root)
    print(
        f"[docs-check] scanned {stats['files']} markdown files, "
        f"{stats['links']} relative links, {stats['anchors']} local anchors, "
        f"{stats['pairs']} language pairs"
    )
    if problems:
        for kind, rel, detail in problems:
            print(f"[FAIL] {kind}: {rel}: {detail}", file=sys.stderr)
        print(f"[docs-check] {len(problems)} problem(s)", file=sys.stderr)
        return 1
    print("[docs-check] OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
